package glitch

import data.glitch_lib

# Set of keywords indicating sensitive data
password_keywords := {"password", "pass", "secret", "credential", "auth_key", "token", "api_key", "access_key", "secret_key"}

# Helper to check if a string contains a hardcoded secret
# Heuristics to reduce false positives: exclude file paths and hex strings
is_hardcoded_secret(str_val) {
    regex.match("(?i)password|secret|token|key", str_val)
    not regex.match("^(conf/|/|\\./|\\w+/).*\\.(keystore|jks|p12|pem)$", str_val)
    not regex.match("^[a-f0-9]{32,}$", str_val)
}

# Check if an attribute name indicates a password field
is_password_attr(name) {
    regex.match("(?i).*password|pass|secret|credential|auth|token|api_key|key.*", name)
}

# Helper to check if a value is a hardcoded secret
# Handles Hash, Array, and String values
has_hardcoded_secret(value) {
    value.ir_type == "String"
    is_hardcoded_secret(value.value)
}

has_hardcoded_secret(value) {
    value.ir_type == "Hash"
    pair := value.value[_]
    pair.key.ir_type == "String"
    is_password_attr(pair.key.value)
    pair.value.ir_type == "String"
    is_hardcoded_secret(pair.value.value)
}

has_hardcoded_secret(value) {
    value.ir_type == "Hash"
    pair := value.value[_]
    has_hardcoded_secret(pair.value)
}

has_hardcoded_secret(value) {
    value.ir_type == "Array"
    elem := value.value[_]
    has_hardcoded_secret(elem)
}

# Check Variables (e.g., Ansible vars, Chef attributes)
Glitch_Analysis[result] {
    parent := glitch_lib._gather_parent_unit_blocks[_]
    parent.path != ""
    vars := glitch_lib.all_variables(parent)
    var := vars[_]
    has_hardcoded_secret(var.value)

    result := {
        "type": "sec_hard_pass",
        "element": var,
        "path": parent.path,
        "description": "Use of Hard-coded Password - Hard-coded passwords in IaC scripts pose a security risk. (CWE-259)"
    }
}

