package glitch

import data.glitch_lib

# Detects hard-coded passwords, secrets, or tokens in variables and attributes
# Handles nested structures (Hash, Array) and multiple IaC technologies (Ansible, Chef, Puppet)

# Keywords indicating potential secrets
secret_keywords := {"password", "pass", "secret", "credential", "auth_key", "token", "api_key", "key", "keystore_password", "truststore_password", "sha512_password"}

# Check if a string value looks like a hard-coded secret
is_hardcoded_secret(str_val) {
    # Basic heuristic: non-empty string that isn't a path or obvious hash
    count(str_val) > 0
    not regex.match("^(conf/|/|\\./|\\w+/).*\\.(keystore|jks|p12|pem)$", str_val)
    not regex.match("^[a-f0-9]{32,}$", str_val)  # Likely a hash, not a password
}

# Check if a key name indicates a secret
is_secret_key(key_str) {
    regex.match("(?i).*password|pass|secret|credential|auth|token|key.*", key_str)
}

# Helper: recursively check a value for hard-coded secrets
check_value(value) {
    value.ir_type == "String"
    is_hardcoded_secret(value.value)
}

check_hash_pairs(value) {
    value.ir_type == "Hash"
    pair := value.value[_]
    pair.key.ir_type == "String"
    is_secret_key(pair.key.value)
    pair.value.ir_type == "String"
    is_hardcoded_secret(pair.value.value)
}

check_hash_values(value) {
    value.ir_type == "Hash"
    pair := value.value[_]
    check_value(pair.value)
}

check_array_elements(value) {
    value.ir_type == "Array"
    elem := value.value[_]
    check_value(elem)
}

# Recursively check nested Hashes and Arrays
check_complex_value(value) {
    value.ir_type == "Hash"
    pair := value.value[_]
    check_complex_value(pair.value)
}

check_complex_value(value) {
    value.ir_type == "Array"
    elem := value.value[_]
    check_complex_value(elem)
}

check_complex_value(value) {
    check_value(value)
}

check_complex_value(value) {
    check_hash_pairs(value)
}

# Rule 1: Detect hard-coded secrets in Variables (e.g., Ansible, Chef, Puppet)
Glitch_Analysis[result] {
    parent := glitch_lib._gather_parent_unit_blocks[_]
    parent.path != ""
    vars := glitch_lib.all_variables(parent)
    var := vars[_]

    # Check direct string value or nested structures
    check_complex_value(var.value)

    result := {
        "type": "sec_hard_pass",
        "element": var,
        "path": parent.path,
        "description": "Use of Hard-coded Password - Hard-coded passwords in IaC scripts pose a security risk. (CWE-259)"
    }
}

# Rule 2: Detect hard-coded secrets in Attributes (e.g., Ansible, Chef, Puppet)
Glitch_Analysis[result] {
    parent := glitch_lib._gather_parent_unit_blocks[_]
    parent.path != ""
    attrs := glitch_lib.all_attributes(parent)
    attr := attrs[_]

    # Check direct string value or nested structures
    check_complex_value(attr.value)

    result := {
        "type": "sec_hard_pass",
        "element": attr,
        "path": parent.path,
        "description": "Use of Hard-coded Password - Hard-coded passwords in IaC scripts pose a security risk. (CWE-259)"
    }
}

